use super::*;use crate::{json,Value,original_group_game};
fn field()->Game{let mut g=Game::new(0,1,742);let template=g.buildings[0].clone();g.map.original=true;g.map.width=64;g.map.height=64;g.map.tiles=vec![0;4096];g.map.terrain_codes=vec![0;4096];g.map.native_terrain_plane=vec![0;16384];g.map.original_tiles=vec![0;4096];g.map.territory=vec![0;4096];g.map.bridge_base=vec![-1;4096];g.units.clear();g.buildings.clear();g.objects.clear();g.crates.clear();g.walls.clear();g.sectors.clear();g.ai_teams.clear();g.native_world=None;g.native_strategy=None;g.native_group_rosters=original_group_game::State::default();for(id,y)in[(10,500.),(11,1500.)]{let mut b=template.clone();b.id=id;b.kind="fort".into();b.team=if id==10{0}else{1};b.hp=900.;b.max_hp=900.;b.x=600.;b.y=y;b.raw_base=Some((300.,y/2.));b.product=None;b.remaining_work=None;b.gate=Some((3000.,3000.));g.buildings.push(b);}g.native_view=Some(([0,0],[2048,2048]));g.import_native_world(&json!({"nativeFortFragments":{"templates":[[0,0,120,0,4,2],[10,10,-140,1,7,5]]}}));g}
#[test]fn only_two_native_fort_slots_construct_and_four_pool_reset_retains_warm_bytes(){let mut g=field();let w=g.native_world.as_mut().unwrap();for p in &w.fort_fragments.pools[..2]{assert_eq!(p.records[0].word(8),120);assert_eq!(p.records[1].bytes[13],7);}for p in &w.fort_fragments.pools[2..]{assert!(p.records.iter().all(|r|r.word(0)==-1));}w.fort_fragments.pools[3].records[7].bytes[4]=19;w.fort_fragments.pools[0].records[0].bytes[17]=71;let previous=w.fort_fragments.clone();let reset=fort_fragments::State::import(Some(&previous),&Value::Null);assert!(reset.pools.iter().all(|p|p.records.iter().all(|r|r.word(0)==-1)));assert_eq!(reset.pools[3].records[7].bytes[4],19);assert_eq!(reset.pools[0].records[0].bytes[17],71);}
#[test]fn fort_pass_uses_live_global_damage_but_never_the_ordinary_dead_minus_two_sentinel(){let mut g=field();for p in &mut g.native_world.as_mut().unwrap().fort_fragments.pools[..2]{p.records[0].set(10,500);p.records[1].set(0,-1);}g.buildings[0].hp=0.;g.buildings[1].hp=900.;g.advance_native_fort_fragments();let w=g.native_world.as_ref().unwrap();assert_eq!(w.fort_fragments.pools[0].records[0].bytes[14]&2,2);assert_eq!(w.fort_fragments.pools[1].records[0].bytes[14]&2,0);}
#[test]fn real_main_runs_one_late_fort_callback_and_retains_its_picture_until_next_main(){let mut g=field();g.spawn("grunt",0,1800.,1800.,1,None);g.spawn("grunt",1,1900.,1800.,2,None);g.maintain_native_group_rosters();g.step(0.059);assert!(g.native_fort_fragment_draws().is_empty());g.step(0.059);let rows=g.native_display_queue().into_iter().filter(|r|r["source"]=="fortFragment").collect::<Vec<_>>();assert_eq!(rows.len(),2);assert!(rows.iter().all(|r|r["palette"]==0&&r["nativeLiteralPalette"]==true));if std::env::var_os("Z_FORT_QUEUE_TRACE").is_some(){println!("FORT_QUEUE {}",serde_json::to_string(&rows).unwrap());}assert_eq!((rows[0]["nativeSlot"].as_u64(),rows[1]["nativeSlot"].as_u64()),(Some(0),Some(1)));assert_eq!(rows[0]["sprite"],120);assert_eq!(rows[0]["stage"],"queue");let phase=g.native_world.as_ref().unwrap().fort_fragments.pools[0].records[0].bytes[12];assert_eq!(phase,0,"one callback decrements delay2 to1; no duplicate fort advancement");g.buildings.clear();assert_eq!(g.native_display_queue().into_iter().filter(|r|r["source"]=="fortFragment").collect::<Vec<_>>(),rows);g.begin_native_display_frame();assert!(g.native_fort_fragment_draws().is_empty());}
#[test]fn optional_all_twenty_campaigns_import_all_build_templates_and_real_fort_constructor(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../dist/original/campaign.json");let Ok(bytes)=std::fs::read(p)else{return;};let data:Value=serde_json::from_slice(&bytes).unwrap();if data["missions"][0].get("nativeFortFragments").is_none(){return;}let mut counts=[0usize;9];for m in data["missions"].as_array().unwrap(){let mut g=Game::new(0,1,742);g.apply_original(m).unwrap();let w=g.native_world.as_ref().unwrap();for raw in m["nativeWorldBuildings"].as_array().unwrap(){let k=raw["kind"].as_i64().unwrap();if ![0,1,4,8].contains(&k){continue;}let slot=raw["nativeSlot"].as_u64().unwrap()as usize;let expect=match k{0=>25,1=>29,4=>34,_=>20};assert_eq!(g.native_building_fragment_test_pool(slot).unwrap().records.iter().filter(|r|r.word(0)!=-1).count(),expect);counts[k as usize]+=1;}for slot in 0..2{assert_eq!(w.fort_fragments.pools[slot].records.iter().filter(|r|r.word(0)!=-1).count(),32);}assert!(w.fort_fragments.pools[2..].iter().all(|p|p.records.iter().all(|r|r.word(0)==-1)));}assert_eq!((counts[0],counts[1],counts[4],counts[8]),(21,80,95,39));}
#[test]fn optional_twenty_authored_missions_run_six_main_callbacks_with_damaged_build_and_fort_pools(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../dist/original/campaign.json");let Ok(bytes)=std::fs::read(p)else{return;};let data:Value=serde_json::from_slice(&bytes).unwrap();if data["missions"][0].get("nativeFortFragments").is_none(){return;}let mut frames=0;for m in data["missions"].as_array().unwrap(){let mut g=Game::new(0,1,742);g.apply_original(m).unwrap();g.ai_teams.clear();for b in &mut g.buildings{if matches!(b.kind.as_str(),"fort"|"vehicle"|"robot"|"radar"){b.hp=(b.max_hp/2.).max(1.);}}for _ in 0..6{g.step(0.059);let rows=g.native_display_queue();assert!(rows.len()<=4000,"mission{}",m["number"]);assert!(rows.iter().filter(|r|r["source"]=="fortFragment").all(|r|r["nativeSlot"].as_u64().is_some_and(|s|s<2)));frames+=1;}}assert_eq!(frames,120);}
